var data = new int[100_000];
for (int i = 0; i < data.Length; i++) data[i] = i;
data[42_000] = -1; data[42_001] = -1;
for (int rep = 0; rep < 50; rep++)
    Cj.Eq(Solution.FirstMatch(data, x => x == -1, 8), 42_000, "lowest index wins, every rep");

// 10M elements, match at index 5. Without Stop() the full scan runs ALL
// 10,000,000 predicate calls; with Stop() it must be orders of magnitude less.
var data = new int[10_000_000];
data[5] = -1;
long calls = 0;
int hit = Solution.FirstMatch(data, x => { System.Threading.Interlocked.Increment(ref calls); return x == -1; }, 4);
Cj.Eq(hit, 5, "finds the early match");
Cj.True(calls < 1_000_000, $"Stop() must cut the scan: {calls:N0} predicate calls (full scan = 10,000,000)");
